    /** The comments on the sheet's claims by claim id, each oldest first. */
    public Map<Long, List<ClaimComment>> comments(String sheetId) {
        return comments.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(ClaimComment::getClaimId, Collectors.toList()));
    }

    /** The claim's comments, oldest first. */
    public List<ClaimComment> commentsOf(Claim claim) {
        return comments.findByClaimIdOrderByIdAsc(claim.getId());
    }

    /** The claim's timeline: the audit lines about it, newest first, as the file holds them. */
    @Transactional(readOnly = true)
    public List<String> timeline(String sheetId, Long id) {
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        return audit.claimLines(sheetId, claim.getNumber(), person.getName(),
                claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(), claim.getDate().toString());
    }

    /**
     * Comment a claim of any status: the comment keeps the user and the sheet's today. Refused for an empty comment.
     */
    @Transactional
    public Claim comment(String sheetId, String user, Long id, String text) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        String written = text == null ? "" : text.trim();
            }
        }
        List<String> activity = new ArrayList<>();
        counts.forEach((user, events) -> events.forEach((event, count) -> activity.add(user + " " + event + " " + count)));
        return activity;
    }

    /**
     * The sheet's records about one claim, exactly as the file holds them, newest first: with a number, those carrying
     * {@code number=} that number; without one, those naming its person (compared as names are compared), amount and
     * date together that carry no number.
     */
    public List<String> claimLines(String sheetId, String number, String person, String amount, String date) {
        String who = person.trim().toLowerCase(Locale.ROOT);
        return lines(sheetId, "").stream().filter(line -> {
            Map<String, String> f = fields(line);
            if (number != null) {
                return number.equals(f.get("number"));
            }
            return !f.containsKey("number") && f.get("person") != null
                    && f.get("person").trim().toLowerCase(Locale.ROOT).equals(who)
                    && amount.equals(f.get("amount")) && date.equals(f.get("date"));
        }).toList();
    }

    /** A record's fields after its event: each {@code key=} with its value up to the next field; the first of a key kept. */
    private static Map<String, String> fields(String line) {
        Map<String, String> fields = new HashMap<>();
        Matcher m = FIELD.matcher(line);
        while (m.find()) {
            fields.putIfAbsent(m.group(1), m.group(2));
        }
        return fields;
    }

    private static boolean isAbout(String line, String who) {
        Matcher m = ABOUT.matcher(line);
        while (m.find()) {
            if (m.group(1).trim().toLowerCase(Locale.ROOT).equals(who)) {
                return true;
            }
        }
        return false;
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
